{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values for stage 1 action selection.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "separate_inverse_temperatures",
      "title": "Separate Inverse Temperatures",
      "description": "Uses distinct inverse temperature parameters for softmax action selection at stage 1 and stage 2.",
      "params": [
        {
          "name": "beta_1",
          "bounds": [0, 10]
        },
        {
          "name": "beta_2",
          "bounds": [0, 10]
        }
      ],
      "evidence": "exp_q1 = np.exp(beta_1 * (q_stage1_net + pers_bonus))\n...\nexp_q2 = np.exp(beta_2 * q_stage2_mf[state_idx])",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates stage 1 model-free values using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * delta_stage1 + learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the stage 1 value of the action chosen in the previous trial.",
      "params": [
        {
          "name": "pers",
          "bounds": [0, 1]
        }
      ],
      "evidence": "pers_bonus = np.zeros(2)\nif last_action_1 != -1:\n    pers_bonus[last_action_1] = pers\n...\nlast_action_1 = action_1[trial]",
      "expressible_in_slots": true
    }
  ]
}
